def estimator_cov(self,method):
        """ Creates covariance matrix for the estimators

        Parameters
        ----------
        method : str
            Estimation method

        Returns
        ----------
        A Covariance Matrix
        """
        if method == 'mle':
            return self.estimator_cov_mle()
        elif method == 'em':
            return self.estimator_cov_em()
        elif method == 'em_mle':
            return self.estimator_cov_em_mle()
        elif method == 'em_mle_robust':
            return self.estimator_cov_em_mle_robust()
        elif method == 'em_mle_robust_diag':
            return self.estimator_cov_em_mle_robust_diag()
        elif method == 'em_mle_robust_diag_inv':
            return self.estimator_cov_em_mle_robust_diag_inv()
        elif method == 'em_mle_robust_diag_inv_inv':
            return self.estimator_cov_em_mle_robust_diag_inv_inv()
        elif method == 'em_mle_robust_diag_inv_inv_inv':
            return self.estimator_cov_em_mle_robust_diag_inv_inv_inv()
        elif method == 'em_mle_robust_diag_inv_inv_inv_inv':
            return self.estimator_cov_em_mle_robust_diag_inv_inv_inv_inv()
        elif method == 'em_mle_robust_diag_inv_inv_inv_inv_inv':
            return self.estimator_cov_em_mle_robust_diag_inv_inv_inv_inv_inv()
        elif method == 'em_mle_robust_diag_inv_inv_inv_inv_inv_inv':
            return self.estimator_cov_em_mle_robust_diag_inv_inv_inv_inv_inv_inv()
        elif method == 'em_mle_robust_diag_inv_inv_inv_inv_inv_inv_inv':
            return self.estimator_cov_em_mle_robust_di

